const fs = require('fs');

const content = fs.readFileSync('README.md', 'utf8');
const headings = content
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'));

fs.writeFileSync('INDEX.md', headings.join('\n') + '\n');
console.log(`Wrote ${headings.length} headings to INDEX.md`);

